    pub fn cmd_copy_buffer_to_image(
        &self,
        cb: VkCommandBuffer,
        src: VkBuffer,
        dst: VkImage,
        layout: VkImageLayout,
        regions: &[VkBufferImageCopy],
    ) -> Result<(), RecordRefused> {
        let facts = self.facts();
        for r in regions {
            facts
                .buffer_image_region(src, dst, r.bufferOffset, &MemoryRegion::of_buffer_copy(r))
                .map_err(RecordRefused::Invalid)?;
        }
        let d = self.recorder(cb).ok_or(RecordRefused::NoDevice)?;
        // SAFETY: as above; the count is the slice's own length, and every region is held to
        // the image and the buffer above.
        unsafe {
            (d.vkCmdCopyBufferToImage())(
                cb,
                src,
                dst,
                layout,
                regions.len() as u32,
                regions.as_ptr(),
            )
        };
        Ok(())
    }

    /// The mirror of [`Self::cmd_copy_buffer_to_image`]: the image is the source, so it is the
    /// image that carries the layout and the buffer that does not.
    pub fn cmd_copy_image_to_buffer(
        &self,
        cb: VkCommandBuffer,
        src: VkImage,
        layout: VkImageLayout,
        dst: VkBuffer,
        regions: &[VkBufferImageCopy],
    ) -> Result<(), RecordRefused> {
        let facts = self.facts();
        for r in regions {
            facts
                .buffer_image_region(dst, src, r.bufferOffset, &MemoryRegion::of_buffer_copy(r))
                .map_err(RecordRefused::Invalid)?;
        }
        let d = self.recorder(cb).ok_or(RecordRefused::NoDevice)?;
        // SAFETY: as above; the count is the slice's own length, and every region is held to
        // the image and the buffer above.
        unsafe {
            (d.vkCmdCopyImageToBuffer())(
                cb,
                src,
                layout,
                dst,
                regions.len() as u32,
                regions.as_ptr(),
            )
        };
        Ok(())
    }

    /// The unscaled sibling of [`Self::cmd_blit_image`]: the regions name one extent, not a
    /// source rectangle and a destination one, so there is nothing for a filter to do.
    pub fn cmd_copy_image(
        &self,
        cb: VkCommandBuffer,
        src: VkImage,
        src_layout: VkImageLayout,
        dst: VkImage,
        dst_layout: VkImageLayout,
        regions: &[VkImageCopy],
    ) -> Result<(), RecordRefused> {
        let facts = self.facts();
        for r in regions {
            facts
                .image_region(
                    Aspects::DepthStencil,
                    src,
                    &r.srcSubresource,
                    r.srcOffset,
                    dst,
                    &r.dstSubresource,
                    r.dstOffset,
                    r.extent,
                )
                .map_err(RecordRefused::Invalid)?;
        }
        let d = self.recorder(cb).ok_or(RecordRefused::NoDevice)?;
        // SAFETY: as above; the count is the slice's own length, and every region is held to
        // both images above.
        unsafe {
            (d.vkCmdCopyImage())(
                cb,
                src,
                src_layout,
                dst,
                dst_layout,
                regions.len() as u32,
                regions.as_ptr(),
            )
        };
        Ok(())
    }

    // Vulkan's own signature: the two images each carry a layout, and the filter is a
    // parameter of the blit rather than of a region.
    #[allow(clippy::too_many_arguments)]
    pub fn cmd_blit_image(
        &self,
        cb: VkCommandBuffer,
        src: VkImage,
        src_layout: VkImageLayout,
        dst: VkImage,
        dst_layout: VkImageLayout,
        regions: &[VkImageBlit],
        filter: VkFilter,
    ) -> Result<(), RecordRefused> {
        let facts = self.facts();
        for r in regions {
            facts
                .blit_region(
                    src,
                    &r.srcSubresource,
                    &r.srcOffsets,
                    dst,
                    &r.dstSubresource,
                    &r.dstOffsets,
                )
                .map_err(RecordRefused::Invalid)?;
        }
        let d = self.recorder(cb).ok_or(RecordRefused::NoDevice)?;
        // SAFETY: as above; the count is the slice's own length, and every region is held to
        // both images above.
        unsafe {
            (d.vkCmdBlitImage())(
                cb,
                src,
                src_layout,
                dst,
                dst_layout,
                regions.len() as u32,
                regions.as_ptr(),
                filter,
            )
        };
        Ok(())
    }

    pub fn cmd_clear_color_image(
        &self,
        cb: VkCommandBuffer,
        image: VkImage,
        layout: VkImageLayout,
        color: &VkClearColorValue,
        ranges: &[VkImageSubresourceRange],
    ) -> Result<(), RecordRefused> {
        let facts = self.facts();
        for r in ranges {
            facts.clear_range(image, r, Clear::Color).map_err(RecordRefused::Invalid)?;
        }
        let d = self.recorder(cb).ok_or(RecordRefused::NoDevice)?;
        // SAFETY: as above; the count is the slice's own length, and the colour is a reference.
        unsafe {
            (d.vkCmdClearColorImage())(
                cb,
                image,
                layout,
                color,
                ranges.len() as u32,
                ranges.as_ptr(),
            )
        };
        Ok(())
    }

    /// `vkCmdCopyBuffer2` and the five other `VK_KHR_copy_commands2` forms, core in 1.3: each
    /// carries its 1.0 twin's arguments in one struct, regions and all, so each is a forward of
    /// the struct the decoder built -- every count in it already reconciled with its array.
    pub fn cmd_copy_buffer2(
        &self,
        cb: VkCommandBuffer,
        info: cs::Decoded<'_, VkCopyBufferInfo2>,
    ) -> Option<()> {
        let f = self.recorder(cb)?.try_vkCmdCopyBuffer2()?;
        // SAFETY: as above; `info` and every array it points at are arena allocations live for
        // the call.
        unsafe { f(cb, info.get()) };
        Some(())
    }

