    /// `vkCmdSetVertexInputEXT`: the whole vertex input state, as two arrays that are counted
    /// separately and mean different things -- bindings, and the attributes read through them.
    ///
    /// Neither count governs the other, so neither is derived from the other: each is its own
    /// slice's length. Either may be empty.
    pub fn cmd_set_vertex_input(
        &self,
        cb: VkCommandBuffer,
        bindings: cs::Decoded<'_, [VkVertexInputBindingDescription2EXT], cs::Checked>,
        attributes: cs::Decoded<'_, [VkVertexInputAttributeDescription2EXT], cs::Checked>,
    ) -> Option<()> {
        let f = self.recorder(cb)?.try_vkCmdSetVertexInputEXT()?;
        // SAFETY: as above; each count is its own slice's length.
        unsafe {
            f(
                cb,
                bindings.len() as u32,
                bindings.as_ptr(),
                attributes.len() as u32,
                attributes.as_ptr(),
            )
        };
        Some(())
    }

    /// `vkCmdSetFragmentShadingRateKHR`: the pipeline's fragment size, and how it combines with
    /// the primitive's rate and the attachment's.
    ///
    /// `size` is a plain extent and `ops` the two combiners by value; the driver reads both
    /// through pointers, which are rebuilt here from what the guest sent.
    pub fn cmd_set_fragment_shading_rate(
        &self,
        cb: VkCommandBuffer,
        size: VkExtent2D,
        ops: [VkFragmentShadingRateCombinerOpKHR; 2],
    ) -> Option<()> {
        let f = self.recorder(cb)?.try_vkCmdSetFragmentShadingRateKHR()?;
        // SAFETY: as above; `size` and `ops` are locals live for the call, and `ops` is the
        // two-element array the entry point reads.
        unsafe { f(cb, &size, ops.as_ptr()) };
        Some(())
    }

    /// `vkCmdBindTransformFeedbackBuffersEXT`: the buffers vertex streams are captured into.
    ///
    /// Three arrays under one count, the sizes optional, as [`Self::cmd_bind_vertex_buffers2`].
    pub fn cmd_bind_transform_feedback_buffers(
        &self,
        cb: VkCommandBuffer,
        first: u32,
        buffers: &[VkBuffer],
        offsets: &[VkDeviceSize],
        sizes: Option<&[VkDeviceSize]>,
    ) -> Option<()> {
        let n = buffers.len();
        assert_eq!(offsets.len(), n, "one count governs every array");
        assert!(sizes.is_none_or(|s| s.len() == n), "one count governs every array");
        let f = self.recorder(cb)?.try_vkCmdBindTransformFeedbackBuffersEXT()?;
        // SAFETY: as above; the count is the length every array present shares, and absent sizes
        // are the null the driver reads as "to the end of each buffer".
        unsafe { f(cb, first, n as u32, buffers.as_ptr(), offsets.as_ptr(), optional(sizes)) };
        Some(())
    }

    /// `vkCmdBeginTransformFeedbackEXT`: start capturing, resuming from the byte counts in
    /// `counters` if there are any.
    pub fn cmd_begin_transform_feedback(
        &self,
        cb: VkCommandBuffer,
        counters: XfbCounters<'_>,
    ) -> Option<()> {
        let f = self.recorder(cb)?.try_vkCmdBeginTransformFeedbackEXT()?;
        let (first, n, buffers, offsets) = counters.raw();
        // SAFETY: as above; `raw` rebuilds the count from the arrays it measures.
        unsafe { f(cb, first, n, buffers, offsets) };
        Some(())
    }

    /// `vkCmdEndTransformFeedbackEXT`: stop capturing, saving the byte counts into `counters` if
    /// there are any.
    pub fn cmd_end_transform_feedback(
        &self,
        cb: VkCommandBuffer,
        counters: XfbCounters<'_>,
    ) -> Option<()> {
        let f = self.recorder(cb)?.try_vkCmdEndTransformFeedbackEXT()?;
        let (first, n, buffers, offsets) = counters.raw();
        // SAFETY: as above; `raw` rebuilds the count from the arrays it measures.
        unsafe { f(cb, first, n, buffers, offsets) };
        Some(())
    }

    /// `vkCmdDrawIndirectByteCountEXT`: a draw whose vertex count is the byte count a transform
    /// feedback pass left in `counter`, divided by `stride`.
    ///
    /// A zero stride is refused: Vulkan requires one above zero, and KosmicKrisp divides by it on
    /// the CPU when it knows the counter, which is a trap on a host whose division by zero traps.
    #[allow(clippy::too_many_arguments)]
    pub fn cmd_draw_indirect_byte_count(
        &self,
        cb: VkCommandBuffer,
        instances: u32,
        first_instance: u32,
        counter: VkBuffer,
        counter_offset: VkDeviceSize,
        vertex_offset: u32,
        stride: u32,
    ) -> Result<(), Unrecorded> {
        if stride == 0 {
            return Err(Unrecorded::Invalid("drew from a transform feedback count with no stride"));
        }
        let f = self
            .drawer(cb, BindPoint::Graphics)?
            .try_vkCmdDrawIndirectByteCountEXT()
            .ok_or(Unrecorded::NoDevice)?;
        // SAFETY: as above.
        unsafe { f(cb, instances, first_instance, counter, counter_offset, vertex_offset, stride) };
        Ok(())
    }

